function StartupPage({ page, jump, notify, openDialog }) {
  if (page === 'Recommended Problems') return <ProblemsPage jump={jump} openDialog={openDialog} />;
  if (page === 'Applications') return <ApplicationsPage jump={jump} />;
  if (page === 'Pilot Journey' || page === 'Milestones & Payments') return <PilotPage openDialog={openDialog} notify={notify} />;
  if (page === 'Trust Passport') return <TrustPage />;
  if (page === 'Documents') return <DocumentsPage notify={notify} />;
  if (page === 'Notifications') return <NotificationsPage notify={notify} />;
  if (page === 'Grievances') return <GrievancePage notify={notify} />;
  if (page === 'Profile') return <StartupProfilePage notify={notify} />;
  return <StartupOverview jump={jump} notify={notify} />;
}

